(function(root){
  const unknown='暂时没有明确方向';
  function toggleTopics(current,value,checked){
    if(!checked)return current.filter(x=>x!==value);
    if(value===unknown)return [unknown];
    return [...current.filter(x=>x!==unknown&&x!==value),value];
  }
  function validate(s,step){
    if(step===0&&!s.role)return '请选择最接近你日常工作的类别。';
    if(step===1){if(!s.topics.length)return '请至少选择一个学习方向，也可以选择暂时没有明确方向。';if(s.topics.includes('网站原型')&&!s.code)return '请选择之前写代码的经历。';}
    if(step===2&&!s.time)return '请选择每周愿意投入的学习时间。';
    return '';
  }
  function summary(s){
    const rows=[['工作类型',s.role],['想学的方向',s.topics.join('、')]];
    if(s.topics.includes('网站原型'))rows.push(['代码经历',s.code]);
    if(s.topics.includes('表格分析'))rows.push(['想解决的表格问题',s.problem.trim()||'暂未填写']);
    rows.push(['每周学习时间',s.time],['给组织者的补充',s.note.trim()||'暂未填写']);return rows;
  }
  const api={toggleTopics,validate,summary};
  if(typeof module!=='undefined')module.exports=api;else root.SurveyLogic=api;
})(typeof globalThis!=='undefined'?globalThis:this);

