const assert=require('node:assert/strict');
const {toggleTopics,validate,summary}=require('./logic');
const s={role:'',topics:[],code:'',problem:'',time:'',note:''};
assert.ok(validate(s,0));s.role='办公协作';assert.equal(validate(s,0),'');
assert.ok(validate(s,1));
s.topics=toggleTopics([], '网站原型',true);assert.ok(validate(s,1));
s.code='没写过';assert.equal(validate(s,1),'');
s.topics=toggleTopics(s.topics,'表格分析',true);s.problem='演示汇总';
assert.ok(summary(s).some(x=>x[1]==='演示汇总'));
s.topics=toggleTopics(s.topics,'暂时没有明确方向',true);
assert.deepEqual(s.topics,['暂时没有明确方向']);
assert.equal(summary(s).some(x=>x[0]==='代码经历'||x[0]==='想解决的表格问题'),false);
s.topics=toggleTopics(s.topics,'表格分析',true);assert.deepEqual(s.topics,['表格分析']);
s.topics=toggleTopics(s.topics,'表格分析',false);assert.ok(validate(s,1));
s.topics=['暂时没有明确方向'];assert.equal(validate(s,1),'');
assert.ok(validate(s,2));s.time='半小时以内';assert.equal(validate(s,2),'');
s.note='<img src=x onerror=alert(1)>';assert.equal(summary(s).at(-1)[1],s.note);
console.log('通过：必填校验、主题互斥、取消选择、条件题及摘要内容规则。');
